using namespace std;

int main() {
    int k;

    while (scanf("%d", &k), k) {
        int s = 0, c;
        // Using a single scanf to read (k * (k - 1) / 2) integers at once
        for (int i = 0; i < k * (k - 1) / 2; i++) {
            scanf("%d", &c);
            s += c;
        }

        // Avoiding division by zero, directly outputting the average
        printf("%d\n", s / (k - 1));
    }

    return 0;
}

